CREATE TABLE collate6log(a, b); CREATE TABLE collate6tab(a COLLATE NOCASE, b COLLATE BINARY); INSERT INTO collate6tab VALUES('a', 'b'); INSERT INTO collate6tab VALUES('A', 'B'); CREATE TRIGGER collate6trig BEFORE INSERT ON collate6tab BEGIN INSERT INTO collate6log VALUES(new.a = 'a', new.b = 'b'); END; INSERT INTO collate6tab VALUES('a', 'b'); INSERT INTO collate6tab VALUES('A', 'B');